import React, { useState, useRef, useEffect } from 'react';
import { attendanceAPI } from './api_service';

const CameraRecognition = ({ addNotification }) => {
  const videoRef = useRef(null);
  const streamRef = useRef(null);
  const captureIntervalRef = useRef(null);
  const isProcessingRef = useRef(false);

  const [loading, setLoading] = useState(false);
  const [result, setResult] = useState(null);
  const [error, setError] = useState(null);
  const [autoMode, setAutoMode] = useState(true);
  const [frameCount, setFrameCount] = useState(0);
  const [lastDetection, setLastDetection] = useState(null);

  useEffect(() => {
    const startCamera = async () => {
      try {
        console.log('🎥 Démarrage caméra...');
        const stream = await navigator.mediaDevices.getUserMedia({
          video: {
            facingMode: 'user',
            width: { ideal: 1280 },
            height: { ideal: 720 }
          },
          audio: false
        });

        streamRef.current = stream;
        if (videoRef.current) {
          videoRef.current.srcObject = stream;
          console.log('✅ Caméra démarrée');
        }
      } catch (err) {
        console.error('❌ Erreur caméra:', err);
        setError('Impossible d\'accéder à la caméra');
        addNotification('❌ Erreur d\'accès caméra', 'error');
      }
    };

    startCamera();

    return () => {
      if (captureIntervalRef.current) {
        clearInterval(captureIntervalRef.current);
      }
      if (streamRef.current) {
        streamRef.current.getTracks().forEach(track => track.stop());
      }
    };
  }, [addNotification]);

  useEffect(() => {
    if (!autoMode) {
      if (captureIntervalRef.current) {
        clearInterval(captureIntervalRef.current);
      }
      return;
    }

    const startCapture = () => {
      console.log('▶️ Mode AUTO - Capture continue activée (500ms)');
      setError(null);

      captureIntervalRef.current = setInterval(async () => {
        if (!videoRef.current || isProcessingRef.current) return;

        try {
          const canvas = document.createElement('canvas');
          canvas.width = videoRef.current.videoWidth || 1280;
          canvas.height = videoRef.current.videoHeight || 720;

          const ctx = canvas.getContext('2d');
          ctx.drawImage(videoRef.current, 0, 0);

          const imageBase64 = canvas.toDataURL('image/jpeg', 0.85);

          isProcessingRef.current = true;
          setFrameCount(prev => prev + 1);

          const response = await attendanceAPI.recognize(imageBase64);
          const data = response?.data;

          console.log('📥 Réponse backend:', data);

          if (data.success && data.student) {
            setResult({
              success: true,
              name: data.student,
              email: data.email || 'N/A',
              confidence: (data.confidence * 100).toFixed(1),
              attendanceId: data.attendance_id,
              timestamp: new Date().toLocaleTimeString(),
              message: `✅ ${data.student} enregistré!`
            });
            setLastDetection(new Date().toLocaleTimeString());
            addNotification(`✅ ${data.student} détecté`, 'success');

            setAutoMode(false);
            console.log('⏸️ Auto-pause après détection');

            setTimeout(() => {
              setAutoMode(true);
            }, 3000);
          }
          else if (data.message === 'Unknown face - no match found') {
            console.log(`⚠️ Non reconnu (confiance: ${data.confidence})`);
          }

        } catch (err) {
          console.warn('⚠️ Erreur requête:', err.message);
        } finally {
          isProcessingRef.current = false;
        }
      }, 500);
    };

    startCapture();

    return () => {
      if (captureIntervalRef.current) {
        clearInterval(captureIntervalRef.current);
      }
    };
  }, [autoMode, addNotification]);

  const handleManualCapture = async () => {
    if (!videoRef.current || loading) return;

    setLoading(true);
    setError(null);
    setResult(null);

    try {
      const canvas = document.createElement('canvas');
      canvas.width = videoRef.current.videoWidth || 1280;
      canvas.height = videoRef.current.videoHeight || 720;

      const ctx = canvas.getContext('2d');
      ctx.drawImage(videoRef.current, 0, 0);

      const imageBase64 = canvas.toDataURL('image/jpeg', 0.92);

      console.log('📸 Capture manuelle envoyée');

      const response = await attendanceAPI.recognize(imageBase64);
      const data = response?.data;

      if (data.success && data.student) {
        setResult({
          success: true,
          name: data.student,
          email: data.email,
          confidence: (data.confidence * 100).toFixed(1),
          attendanceId: data.attendance_id,
          timestamp: new Date().toLocaleTimeString(),
          message: `✅ ${data.student} enregistré!`
        });
        addNotification(`✅ ${data.student} détecté`, 'success');
      } else {
        setError(data.message || 'Visage non reconnu');
        setResult({
          success: false,
          message: data.message || 'Non reconnu',
          confidence: ((data.confidence || 0) * 100).toFixed(1)
        });
        addNotification('⚠️ Visage non reconnu', 'error');
      }
    } catch (err) {
      const msg = err?.message || 'Erreur serveur';
      setError(msg);
      addNotification(`❌ ${msg}`, 'error');
    } finally {
      setLoading(false);
    }
  };

  const stopCamera = () => {
    if (captureIntervalRef.current) {
      clearInterval(captureIntervalRef.current);
    }
    if (streamRef.current) {
      streamRef.current.getTracks().forEach(track => track.stop());
    }
    if (videoRef.current) {
      videoRef.current.srcObject = null;
    }
    setAutoMode(false);
    console.log('🛑 Caméra arrêtée');
  };

  return (
    <div style={styles.container}>
      <h1 style={styles.title}>👤 Reconnaissance Faciale</h1>

      <div style={styles.videoContainer}>
        <video
          ref={videoRef}
          autoPlay
          playsInline
          muted
          style={styles.video}
        />

        <div style={{
          ...styles.statusBadge,
          background: autoMode ? 'rgba(34, 197, 94, 0.9)' : 'rgba(107, 114, 128, 0.9)'
        }}>
          {autoMode ? '🔄 Scanning...' : '⏸️ Pause'}
        </div>

        <div style={styles.frameCounter}>
          Frames: {frameCount}
        </div>
      </div>

      <div style={styles.actions}>
        <button
          onClick={handleManualCapture}
          disabled={loading}
          style={{
            ...styles.btn,
            background: loading ? '#94A3B8' : '#10B981'
          }}
        >
          {loading ? '⏳ Traitement...' : '📸 Capturer'}
        </button>

        <button
          onClick={() => setAutoMode(!autoMode)}
          style={{
            ...styles.btn,
            background: autoMode ? '#EF4444' : '#6366F1'
          }}
        >
          {autoMode ? '⏸️ Arrêter Auto' : '▶️ Démarrer Auto'}
        </button>

        <button
          onClick={stopCamera}
          style={{
            ...styles.btn,
            background: '#64748B'
          }}
        >
          🛑 Fermer Caméra
        </button>
      </div>

      {autoMode && (
        <div style={styles.autoStatus}>
          <span style={styles.pulse} />
          Détection continue en cours... (500ms)
        </div>
      )}

      {lastDetection && (
        <div style={styles.lastDetectionBox}>
          ⏰ Dernière détection: {lastDetection}
        </div>
      )}

      {error && (
        <div style={styles.errorBox}>
          ❌ {error}
        </div>
      )}

      {result && (
        <div style={{
          ...styles.resultBox,
          borderLeft: result.success ? '4px solid #10B981' : '4px solid #EF4444'
        }}>
          {result.success ? (
            <>
              <h3 style={{ color: '#10B981', margin: '0 0 12px 0' }}>
                {result.message}
              </h3>
              <div style={styles.resultGrid}>
                <p><strong>👤 Nom:</strong> {result.name}</p>
                <p><strong>📧 Email:</strong> {result.email}</p>
                <p><strong>🎯 Confiance:</strong> {result.confidence}%</p>
                <p><strong>🆔 ID Présence:</strong> {result.attendanceId}</p>
                <p><strong>🕒 Heure:</strong> {result.timestamp}</p>
              </div>
            </>
          ) : (
            <>
              <h3 style={{ color: '#EF4444', margin: '0 0 8px 0' }}>❌ Non Reconnu</h3>
              <p style={{ margin: 0 }}>{result.message}</p>
              <p style={{ margin: '4px 0 0 0', fontSize: '0.85rem', color: '#666' }}>
                Confiance: {result.confidence}%
              </p>
            </>
          )}
        </div>
      )}

      <div style={styles.debugBox}>
        <p><strong>Mode Auto:</strong> {autoMode ? '✅ ON' : '❌ OFF'}</p>
        <p><strong>Frames traités:</strong> {frameCount}</p>
        <p><strong>En traitement:</strong> {isProcessingRef.current ? '🔄 OUI' : '✓ NON'}</p>
      </div>
    </div>
  );
};

